// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.base.AbstractIRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreIriRecordCodecTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void releasedLegacyFormatKeepsTheSuppliedLocalName() {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		StoreProperties properties = new StoreProperties(temporaryDirectory.toFile());
		properties.setVersion("2");
		LmdbStoreFormat format = LmdbStoreFormat.fromProperties(properties, config);
		IRI supplied = SimpleValueFactory.getInstance().createIRI("urn:codec:", "nested:value");

		byte[] encoded = ValueStoreRecordCodec.iriData(supplied, 1000L, format);

		assertThat(encoded).isEqualTo(ValueStoreRecordCodec.iriData(supplied, 1000L));
		assertThat(localName(encoded, 1000L)).isEqualTo("nested:value");
		assertThat(IriStorageEncoding.split(supplied, format).namespace()).isEqualTo("urn:codec:");
		assertThat(IriStorageEncoding.namespace(supplied, format)).isEqualTo("urn:codec:");
		assertThat(IriStorageEncoding.localName(supplied, format)).isEqualTo("nested:value");
	}

	@Test
	void unreleasedFormatSixCannotSelectAnIriCodec() {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		StoreProperties properties = new StoreProperties().setVersion("6");
		assertThatThrownBy(() -> LmdbStoreFormat.fromProperties(properties, config))
				.isInstanceOf(SailException.class)
				.hasMessageContaining("Unsupported LmdbStore version: 6");
	}

	@Test
	void canonicalEncodingNeverConsultsCallerProvidedNamespaceOrLocalName() {
		IRI supplied = new AbstractIRI() {
			@Override
			public String stringValue() {
				return "https://EXAMPLE.test/a/%2f/../é#😀/tail:part#second";
			}

			@Override
			public String getNamespace() {
				throw new AssertionError("Canonical encoding must not read the caller's namespace");
			}

			@Override
			public String getLocalName() {
				throw new AssertionError("Canonical encoding must not read the caller's local name");
			}
		};
		LmdbStoreFormat format = LmdbStoreFormat.forNewStore(new LmdbStoreConfig());
		IriStorageEncoding.Split split = IriStorageEncoding.split(supplied, format);

		assertThat(split.namespace()).isEqualTo("https://EXAMPLE.test/a/%2f/../é#");
		assertThat(split.localName()).isEqualTo("😀/tail:part#second");
		assertThat(IriStorageEncoding.namespace(supplied, format)).isEqualTo(split.namespace());
		assertThat(IriStorageEncoding.localName(supplied, format)).isEqualTo(split.localName());
		assertThat(split.namespace() + split.localName()).isEqualTo(supplied.stringValue());
		byte[] encoded = ValueStoreRecordCodec.iriData(supplied, 1000L, format);
		assertThat(encoded).isEqualTo(ValueStoreRecordCodec.iriData(split, 1000L));
		assertThat(localName(encoded, 1000L)).isEqualTo(split.localName());
	}

	private static String localName(byte[] record, long expectedNamespaceId) {
		ByteBuffer bytes = ByteBuffer.wrap(record);
		assertThat(bytes.get()).isEqualTo(ValueStoreRecordCodec.URI_VALUE);
		assertThat(Varint.readUnsigned(bytes)).isEqualTo(expectedNamespaceId);
		return new String(record, bytes.position(), bytes.remaining(), StandardCharsets.UTF_8);
	}
}
